/*
 * ebooks.bucklerfamily.estate/read/* -> the root repository's published reader.
 * The upstream HTML is generated by bucklerfamily-estate's build. Requests for
 * /api/free stay on this host and continue to the existing ebook-gate Worker.
 */
addEventListener("fetch", event => {
  event.respondWith(handleRequest(event.request));
});

async function handleRequest(request) {
  if (request.method !== "GET" && request.method !== "HEAD") {
    return new Response("Method Not Allowed", {
      status: 405,
      headers: { "Allow": "GET, HEAD", "Content-Type": "text/plain; charset=utf-8" }
    });
  }

  const incoming = new URL(request.url);
  if (!incoming.pathname.startsWith("/read/")) {
    return new Response("Not Found", { status: 404 });
  }

  // Fixed upstream host and path prefix: no user-controlled host or open proxy.
  const suffix = incoming.pathname.slice("/read".length);
  const upstream = new URL(
    "https://bucklerfamily.estate/reader-root-v131/read" + suffix + incoming.search
  );

  let response;
  try {
    response = await fetch(upstream.toString(), {
      method: request.method,
      headers: { "Accept": "text/html" },
      redirect: "follow"
    });
  } catch (_) {
    return new Response("The e-book reader is temporarily unavailable.", {
      status: 502,
      headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" }
    });
  }

  const headers = new Headers(response.headers);
  headers.delete("x-frame-options");

  // The parent is the main BucklerFamily.estate site. Preserve all other CSP
  // directives from the root site while allowing that page to embed this reader.
  const csp = headers.get("content-security-policy") || "";
  const directives = csp.split(";")
    .map(part => part.trim())
    .filter(part => part && !/^frame-ancestors\b/i.test(part));
  directives.push("frame-ancestors https://bucklerfamily.estate");
  headers.set("content-security-policy", directives.join("; "));
  headers.set("x-ebook-reader-source", "bucklerfamily-estate:site");

  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers
  });
}
